// The workflow the schedule starts: one poll of one Jira query.
export async function pollJira(name: string): Promise<number> {
  return peopleApis.startMatches(name);
}

// The activity that does the work: search Jira, then start or join one run per ticket.
export const startMatches = async (name: string): Promise<number> => {
  const q = QUERIES.get(name)!;
  const issues = await jira.searchAll(q.jql);
  for (const issue of issues) {
    const start = await q.toStart(issue);
    if (!start) continue;
    await startRun(await temporalClient(), q.agent, issue.key, ...start);
  }
  return issues.length;
};

import { ScheduleAlreadyRunning, ScheduleOverlapPolicy, type Client } from "@temporalio/client";

export const ensureSchedules = async (client: Client): Promise<void> => {
  for (const q of QUERIES.values()) {
    const scheduleId = `poll-jira-${q.name}`;
    const schedule = {
      spec: { intervals: [{ every: q.every }] },
      action: { type: "startWorkflow" as const, workflowType: pollJira, args: [q.name],
        workflowId: scheduleId, taskQueue: "ai-agents-orchestrator" },
      policies: { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: q.every },
    };
    await client.schedule.create({ scheduleId, ...schedule }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((previous) => ({ ...previous, ...schedule }));
    });
  }
};

