      taskQueue: 'ai-agents-nova',
      workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING,
      args: [ticket],
    });
    console.log(`${time()}  poll: ${ticket} → ${handle.workflowId}  run ${handle.firstExecutionRunId.slice(-8)}`);
  }
  return jira.assignedToNova.length;
};
