import { condition, defineSignal, proxyActivities, setHandler } from '@temporalio/workflow';

const { startMatches } = proxyActivities({ startToCloseTimeout: '5 minutes' });

// Started by the schedule: one poll of Jira per run.
export async function pollJira() {
  return startMatches();
}

// Nova's run for one ticket, cut down to "wait until someone approves".
export const approve = defineSignal('approve');
export async function ticketToPr(ticket) {
  let approvedBy;
  setHandler(approve, (who) => {
    approvedBy = who;
  });
  await condition(() => approvedBy !== undefined, '1 day');
  return `${ticket} approved by ${approvedBy}`;
}
EOF

