// ensure-schedule.mjs: create the poll schedule, or update it when it exists. Safe to run twice.
import { Client, Connection, ScheduleAlreadyRunning, ScheduleOverlapPolicy } from '@temporalio/client';

const client = new Client({ connection: await Connection.connect({ address: 'localhost:7233' }) });
const scheduleId = 'poll-jira-nova';
const schedule = {
  action: { type: 'startWorkflow', workflowType: 'pollJira', workflowId: scheduleId, taskQueue: 'ai-agents-orchestrator' },
  spec: { intervals: [{ every: '10 seconds' }] },
  policies: { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: '10 seconds' },
};
try {
  await client.schedule.create({ scheduleId, ...schedule });
  console.log(`created ${scheduleId}`);
} catch (err) {
  if (!(err instanceof ScheduleAlreadyRunning)) throw err;
  await client.schedule.getHandle(scheduleId).update((previous) => ({ ...previous, ...schedule }));
  console.log(`updated ${scheduleId}`);
}
await client.connection.close();
